inline console::NativeProfile<profile_data::rules> nativeProfile;
template<uintptr_t Reference> uintptr_t Address() { return nativeProfile.template get<Reference>(); }
inline uintptr_t Address(uintptr_t reference) { return nativeProfile.get(reference); }
inline bool InitializeAddresses() {
    // Validation must see original instructions throughout the scan. Running
    // game threads can otherwise replace them with JIT markers after the flush.
    int dispatch = sceKernelSuspendDispatchThread();
    sceKernelIcacheInvalidateRange(reinterpret_cast<void*>(pattern.text_addr),pattern.text_size);
    bool valid = nativeProfile.initialize({pattern.text_addr,reinterpret_cast<const uint8_t*>(pattern.text_addr),pattern.text_size,console::portable::gameGP});
    sceKernelResumeDispatchThread(dispatch);
    return valid;
}
